cd ..; head -3 responses.csv; wc -l responses.csv; python3 -c "
import csv,collections
r=list(csv.DictReader(open('responses.csv')))
c=collections.defaultdict(list)
for x in r: c[x['number_set']].append((int(x['target']),int(x['rating'])))
for s,v in c.items():
  d=collections.defaultdict(list)
  for t,y in v: d[t].append(y)
  print(s, len(v), ' '.join(f'{t}:{sum(y)}/{len(y)}' for t,y in sorted(d.items())))
"; ls ../model_loop/iter_4/critique 2>/dev/null; ls iter_4

